// Map shapes: a tile from civ-core's starting map, and a tile as the map board draws it.

import type { CivIndex, ResourceKind, UnitKind } from "./game";

/** One tile of the starting map, as generated by civ-core. */
export type MapTile = {
  x: number;
  y: number;
  owner: CivIndex | null;
  deposit: ResourceKind | null;
  isCity: boolean;
};

/** A tile as the map board draws it at some turn. */
export type BoardTile = MapTile & {
  /** Two civs reach this tile at nearly the same time. */
  isContested: boolean;
  unit: UnitKind | null;
};

/** A board at one turn, plus how many tiles each civ owns. */
export type BoardState = {
  tiles: BoardTile[];
  tilesByCiv: Record<CivIndex, number>;
};
